R=Path(__file__).resolve().parents[1]
def write(p,x): (R/p).write_text(json.dumps(x,indent=2,ensure_ascii=False,allow_nan=False)+'\n')
def obj(p):return {'type':'object','properties':p,'required':list(p),'additionalProperties':False}
def arr(items,minItems=1):return {'type':'array','items':items,'minItems':minItems}
def num(lo=None,hi=None,nullable=False):
 d={'type':['number','null'] if nullable else 'number'}
 if lo is not None:d['minimum']=lo
 if hi is not None:d['maximum']=hi
 return d
def enum(*x):return {'enum':list(x)}
def text(nullable=False):return {'type':['string','null'] if nullable else 'string','minLength':1}
def nullable(d):return {'anyOf':[d,{'type':'null'}]}
def emap(value):return {'type':'object','minProperties':1,'propertyNames':{'enum':['Al','Si','O']},'additionalProperties':value}
